156	/* NSH-safe single-quote wrap; reject embedded quotes */
157	static int shell_quote(const char *in, char *out, size_t outsz)
158	{
159	  size_t n;
160	  size_t o = 0;
161	
162	  if (!in || !out || outsz < 3)
163	    {
164	      return -1;
165	    }
166	  if (strchr(in, '\'') != NULL)
167	    {
168	      return -1;
169	    }
170	  n = strlen(in);
171	  if (n + 3 > outsz)
172	    {
173	      return -1;
174	    }
175	  out[o++] = '\'';
176	  memcpy(out + o, in, n);
177	  o += n;
178	  out[o++] = '\'';
179	  out[o] = 0;
180	  return 0;
181	}
