183	static void cli_sta_up(void)
184	{
185	  /* Official §9 + review: ifup FIRST, then STA mode, ifup again.
186	   * Do not ifdown — avoid tearing radio before psk. */
187	  syslog(LOG_INFO, "[deskmate-wifi] ifup → mode STA → ifup\n");
188	  (void)system("ifup wlan0");
189	  (void)system("wapi mode wlan0 2");
190	  (void)system("ifup wlan0");
191	  (void)system("wapi power_save wlan0 off");
192	  (void)system("wapi country wlan0 CN");
193	}
