208	static void wifi_cred_save(const char *ssid, const char *pass)
209	{
210	  FILE *f;
211	
212	  if (!ssid || !ssid[0])
213	    {
214	      return;
215	    }
216	  f = fopen(DM_WIFI_SAVE_PATH, "w");
217	  if (!f)
218	    {
219	      return;
220	    }
221	  fprintf(f, "%s\n%s\n", ssid, pass ? pass : "");
222	  fclose(f);
223	}
