225	static int wifi_cred_load(char *ssid, size_t slen, char *pass, size_t plen)
226	{
227	  FILE *f = fopen(DM_WIFI_SAVE_PATH, "r");
228	  char line[80];
229	
230	  if (!f)
231	    {
232	      return -1;
233	    }
234	  if (!fgets(line, sizeof(line), f))
235	    {
236	      fclose(f);
237	      return -1;
238	    }
239	  line[strcspn(line, "\r\n")] = 0;
240	  if (!line[0])
241	    {
242	      fclose(f);
243	      return -1;
244	    }
245	  snprintf(ssid, slen, "%s", line);
246	  if (fgets(line, sizeof(line), f))
247	    {
248	      line[strcspn(line, "\r\n")] = 0;
249	      snprintf(pass, plen, "%s", line);
250	    }
251	  else
252	    {
253	      pass[0] = 0;
254	    }
255	  fclose(f);
256	  return 0;
257	}
