259	/* Board r528_late_initialize already runs realtek_wlan_bringup().
260	 * App must NOT call driver init (data abort). Wait longer for wlan0:
261	 * board STA bringup can finish after deskmate starts. */
262	static int ensure_driver_wait(int attempts_100ms)
263	{
264	  int i;
265	
266	  if (s_drv_ready && if_nametoindex(DM_WIFI_IF) != 0)
267	    {
268	      return 0;
269	    }
270	
271	  for (i = 0; i < attempts_100ms; i++)
272	    {
273	      if (if_nametoindex(DM_WIFI_IF) != 0)
274	        {
275	          s_drv_ready = 1;
276	          syslog(LOG_INFO, "[deskmate-wifi] %s ready\n", DM_WIFI_IF);
277	          return 0;
278	        }
279	      usleep(100 * 1000);
280	    }
281	
282	  s_drv_ready = 0;
283	  syslog(LOG_ERR,
284	         "[deskmate-wifi] %s missing — board bringup not ready yet\n",
285	         DM_WIFI_IF);
286	  return -1;
287	}
