295	static int collect_aps(int sock)
296	{
297	  struct wapi_list_s list;
298	  struct wapi_scan_info_s *ap;
299	  int n = 0;
300	  int ret;
301	
302	  memset(&list, 0, sizeof(list));
303	  ret = wapi_scan_coll(sock, DM_WIFI_IF, &list);
304	  pthread_mutex_lock(&s_lock);
305	  s_ap_n = 0;
306	  if (ret >= 0)
307	    {
308	      for (ap = list.head.scan; ap && n < DM_WIFI_AP_MAX; ap = ap->next)
309	        {
310	          if (!ap->has_essid || ap->essid[0] == 0)
311	            {
312	              continue;
313	            }
314	          strncpy(s_aps[n].ssid, ap->essid, sizeof(s_aps[n].ssid) - 1);
315	          s_aps[n].ssid[sizeof(s_aps[n].ssid) - 1] = 0;
316	          s_aps[n].rssi = ap->has_rssi ? ap->rssi : 0;
317	          s_aps[n].open = (!ap->has_encode) || (ap->encode == 0);
318	          n++;
319	        }
320	      s_ap_n = n;
321	    }
322	  pthread_mutex_unlock(&s_lock);
323	  wapi_scan_coll_free(&list);
324	  return ret;
325	}
