327	/* same steps as apps/wireless/wapi wapi_scan_cmd */
328	static void *scan_thread(void *arg)
329	{
330	  int sock;
331	  int ret;
332	  int wait;
333	  int attempt;
334	
335	  (void)arg;
336	
337	  if (ensure_driver() < 0)
338	    {
339	      s_scan_busy = 0;
340	      s_scan_ready = 1;
341	      return NULL;
342	    }
343	
344	  cli_sta_up();
345	
346	  sock = wapi_make_socket();
347	  if (sock < 0)
348	    {
349	      s_scan_busy = 0;
350	      s_scan_ready = 1;
351	      return NULL;
352	    }
353	
354	  wapi_set_mode(sock, DM_WIFI_IF, WAPI_MODE_MANAGED);
355	  wapi_set_ifup(sock, DM_WIFI_IF);
356	  (void)wapi_set_power_save(sock, DM_WIFI_IF, false);
357	
358	  for (attempt = 0; attempt < 2; attempt++)
359	    {
360	      ret = wapi_escan_init(sock, DM_WIFI_IF, IW_SCAN_TYPE_ACTIVE, NULL);
361	      if (ret < 0)
362	        {
363	          continue;
364	        }
365	
366	      /* official: 0 = data ready, 1 = not ready */
367	      for (wait = 0; wait < 50; wait++)
368	        {
369	          usleep(200 * 1000);
370	          ret = wapi_scan_stat(sock, DM_WIFI_IF);
371	          if (ret == 0)
372	            {
373	              break;
374	            }
375	        }
376	
377	      collect_aps(sock);
378	      if (s_ap_n > 0)
379	        {
380	          break;
381	        }
382	    }
383	
384	  close(sock);
385	  s_scan_busy = 0;
386	  s_scan_ready = 1;
387	  return NULL;
388	}
