390	int dm_wifi_start_scan(void)
391	{
392	  pthread_t th;
393	  pthread_attr_t attr;
394	  int ret;
395	
396	  if (s_scan_busy || s_conn_busy)
397	    {
398	      return -1;
399	    }
400	
401	  s_scan_ready = 0;
402	  s_scan_busy = 1;
403	  pthread_attr_init(&attr);
404	  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
405	  ret = pthread_create(&th, &attr, scan_thread, NULL);
406	  pthread_attr_destroy(&attr);
407	  if (ret != 0)
408	    {
409	      s_scan_busy = 0;
410	      return -1;
411	    }
412	  pthread_detach(th);
413	  return 0;
414	}
