416	/* Official connect — ifup → mode → psk(ccmp=3) → essid(1) → wait → renew */
417	static void *conn_thread(void *arg)
418	{
419	  char cmd[192];
420	  char qssid[80];
421	  char qpass[160];
422	  int ret;
423	  int i;
424	  int got_ip = 0;
425	  struct in_addr addr;
426	  char try_ssid[33];
427	  char try_pass[64];
428	
429	  (void)arg;
430	
431	  strncpy(try_ssid, s_pending_ssid, sizeof(try_ssid) - 1);
432	  try_ssid[sizeof(try_ssid) - 1] = 0;
433	  strncpy(try_pass, s_pending_pass, sizeof(try_pass) - 1);
434	  try_pass[sizeof(try_pass) - 1] = 0;
435	
436	  if (try_ssid[0] == 0 || if_nametoindex(DM_WIFI_IF) == 0)
437	    {
438	      syslog(LOG_ERR, "[deskmate-wifi] connect abort: no ssid/wlan0\n");
439	      s_conn_busy = 0;
440	      s_conn_fail = 1;
441	      return NULL;
442	    }
443	
444	  if (ensure_driver() < 0)
445	    {
446	      s_conn_busy = 0;
447	      s_conn_fail = 1;
448	      return NULL;
449	    }
450	
451	  /* 1) ifup + STA mode (separate system calls — no NSH &&) */
452	  cli_sta_up();
453	
454	  /* 2) psk — WPA_ALG_CCMP = 3 (guide §1.3.2 / §9.2) */
455	  if (!s_pending_open && s_pending_pass[0])
456	    {
457	      if (shell_quote(s_pending_pass, qpass, sizeof(qpass)) < 0)
458	        {
459	          s_conn_busy = 0;
460	          s_conn_fail = 1;
461	          return NULL;
462	        }
463	      snprintf(cmd, sizeof(cmd), "wapi psk %s %s 3", DM_WIFI_IF, qpass);
464	      syslog(LOG_INFO, "[deskmate-wifi] %s\n", cmd);
465	      (void)system(cmd);
466	
467	      /* optional explicit WPA2 version — ignore failure */
468	      snprintf(cmd, sizeof(cmd), "wapi psk %s %s 3 2", DM_WIFI_IF, qpass);
469	      (void)system(cmd);
470	    }
471	
472	  /* 3) essid — flag 1 = connect */
473	  if (shell_quote(s_pending_ssid, qssid, sizeof(qssid)) < 0)
474	    {
475	      s_conn_busy = 0;
476	      s_conn_fail = 1;
477	      return NULL;
478	    }
479	  snprintf(cmd, sizeof(cmd), "wapi essid %s %s 1", DM_WIFI_IF, qssid);
480	  syslog(LOG_INFO, "[deskmate-wifi] %s\n", cmd);
481	  (void)system(cmd);
482	
483	  /* 4) WPA2 4-way handshake / associate */
484	  sleep(3);
485	
486	  /* 5) DHCP renew — retry loop (review: 2s too short once is not enough) */
487	  for (i = 0; i < 5; i++)
488	    {
489	      (void)system("renew wlan0");
490	      ret = netlib_obtain_ipv4addr(DM_WIFI_IF);
491	      if (ret >= 0 && wifi_get_valid_ip(&addr) == 0)
492	        {
493	          got_ip = 1;
494	          break;
495	        }
496	      syslog(LOG_WARNING, "[deskmate-wifi] renew retry %d\n", i + 1);
497	      sleep(3);
498	    }
499	
500	  pthread_mutex_lock(&s_lock);
501	  strncpy(s_cur_ssid, try_ssid, sizeof(s_cur_ssid) - 1);
502	  s_cur_ssid[sizeof(s_cur_ssid) - 1] = 0;
503	  if (got_ip)
504	    {
505	      strncpy(s_cur_ip, inet_ntoa(addr), sizeof(s_cur_ip) - 1);
506	      s_cur_ip[sizeof(s_cur_ip) - 1] = 0;
507	    }
508	  else
509	    {
510	      s_cur_ip[0] = 0;
511	    }
512	  pthread_mutex_unlock(&s_lock);
513	
514	  if (!got_ip)
515	    {
516	      syslog(LOG_ERR,
517	             "[deskmate-wifi] connect fail: no IP after renew "
518	             "(ssid=%s wlan0=%d)\n",
519	             try_ssid, (int)if_nametoindex(DM_WIFI_IF));
520	      s_conn_busy = 0;
521	      s_conn_fail = 1;
522	      return NULL;
523	    }
524	
525	  syslog(LOG_INFO, "[deskmate-wifi] connected ssid=%s ip=%s\n",
526	         s_cur_ssid, s_cur_ip);
527	
528	  (void)system("wapi save_config wlan0");
529	  wifi_cred_save(try_ssid, try_pass);
530	
531	  s_conn_busy = 0;
532	  s_conn_ok = 1;
533	  return NULL;
534	}
535	
536	int dm_wifi_connect(const char *ssid, const char *pass)
537	{
538	  pthread_t th;
539	  pthread_attr_t attr;
540	  int ret;
541	
542	  if (!ssid || !ssid[0] || s_scan_busy || s_conn_busy)
543	    {
544	      return -1;
545	    }
546	
547	  strncpy(s_pending_ssid, ssid, sizeof(s_pending_ssid) - 1);
548	  s_pending_ssid[sizeof(s_pending_ssid) - 1] = 0;
549	  if (pass)
550	    {
551	      strncpy(s_pending_pass, pass, sizeof(s_pending_pass) - 1);
552	      s_pending_pass[sizeof(s_pending_pass) - 1] = 0;
553	    }
554	  else
555	    {
556	      s_pending_pass[0] = 0;
557	    }
558	  s_pending_open = (s_pending_pass[0] == 0);
559	
560	  s_conn_ok = 0;
561	  s_conn_fail = 0;
562	  s_conn_busy = 1;
563	
564	  pthread_attr_init(&attr);
565	  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
566	  ret = pthread_create(&th, &attr, conn_thread, NULL);
567	  pthread_attr_destroy(&attr);
568	  if (ret != 0)
569	    {
570	      s_conn_busy = 0;
571	      return -1;
572	    }
573	  pthread_detach(th);
574	  return 0;
575	}
