577	/* Boot auto-connect with retry until wlan0 appears.
578	 * Manual scan/connect UI remains fully available. */
579	static void *auto_thread(void *arg)
580	{
581	  char ssid[33];
582	  char pass[64];
583	  int round;
584	
585	  (void)arg;
586	
587	  ssid[0] = 0;
588	  pass[0] = 0;
589	  if (wifi_cred_load(ssid, sizeof(ssid), pass, sizeof(pass)) != 0 ||
590	      !ssid[0])
591	    {
592	      snprintf(ssid, sizeof(ssid), "%s", DM_WIFI_AUTO_SSID);
593	      snprintf(pass, sizeof(pass), "%s", DM_WIFI_AUTO_PSK);
594	    }
595	
596	  syslog(LOG_INFO,
597	         "[deskmate-wifi] auto-connect ssid=%s — wait wlan0 first\n", ssid);
598	
599	  for (round = 0; round < 8; round++)
600	    {
601	      /* Board bringup must finish first — do not call wapi before wlan0 */
602	      if (ensure_driver_wait(300) < 0)
603	        {
604	          syslog(LOG_WARNING,
605	                 "[deskmate-wifi] wlan0 not ready, round=%d "
606	                 "(waiting for board SDIO probe)\n", round);
607	          sleep(5);
608	          continue;
609	        }
610	
611	      if (dm_wifi_connected())
612	        {
613	          syslog(LOG_INFO, "[deskmate-wifi] already connected\n");
614	          return NULL;
615	        }
616	
617	      dm_wifi_clear_conn_flags();
618	      if (dm_wifi_connect(ssid, pass) != 0)
619	        {
620	          syslog(LOG_WARNING, "[deskmate-wifi] connect start busy/fail\n");
621	          sleep(5);
622	          continue;
623	        }
624	
625	      /* conn_thread: ifup→psk→essid→3s→renew×5 */
626	      sleep(20);
627	      if (dm_wifi_connected())
628	        {
629	          syslog(LOG_INFO, "[deskmate-wifi] auto connected ssid=%s ip=%s\n",
630	                 dm_wifi_cur_ssid(), dm_wifi_cur_ip());
631	          dm_wifi_clear_conn_flags();
632	          return NULL;
633	        }
634	
635	      syslog(LOG_WARNING, "[deskmate-wifi] auto connect not ready, retry\n");
636	      dm_wifi_clear_conn_flags();
637	      sleep(5);
638	    }
639	
640	  syslog(LOG_ERR,
641	         "[deskmate-wifi] auto-connect gave up; use manual UI after wlan0\n");
642	  return NULL;
643	}
644	
645	void dm_wifi_auto_start(void)
646	{
647	  pthread_t th;
648	  pthread_attr_t attr;
649	
650	  if (s_auto_started)
651	    {
652	      return;
653	    }
654	  s_auto_started = 1;
655	
656	  pthread_attr_init(&attr);
657	  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
658	  if (pthread_create(&th, &attr, auto_thread, NULL) == 0)
659	    {
660	      pthread_detach(th);
661	    }
662	  pthread_attr_destroy(&attr);
663	}
