65	static void refresh_wifi_header(void)
66	{
67	  if (s_cur_ssid_l)
68	    {
69	      lv_label_set_text(s_cur_ssid_l,
70	                        dm_wifi_connected() ? dm_wifi_cur_ssid()
71	                                            : dm_t("未连接", "Disconnected"));
72	    }
73	  if (s_cur_ip_l)
74	    {
75	      lv_label_set_text(s_cur_ip_l,
76	                        dm_wifi_connected() ? dm_wifi_cur_ip() : "—");
77	    }
78	  if (s_cur_state_l)
79	    {
80	      lv_label_set_text(s_cur_state_l,
81	                        dm_t(dm_wifi_connected() ? "已连接" : "离线",
82	                             dm_wifi_connected() ? "Online" : "Offline"));
83	      lv_obj_set_style_text_color(
84	          s_cur_state_l,
85	          lv_color_hex(dm_wifi_connected() ? C_OK : C_MUTED), LV_PART_MAIN);
86	    }
87	  if (s_wifi_sub)
88	    {
89	      if (dm_wifi_connected())
90	        {
91	          lv_label_set_text(s_wifi_sub, dm_wifi_cur_ssid());
92	        }
93	      else
94	        {
95	          lv_label_set_text(s_wifi_sub, dm_t("未连接", "Disconnected"));
96	        }
97	    }
98	}
