100	static void refresh_ap_list(void)
101	{
102	  int n = dm_wifi_ap_count();
103	  int sel = dm_wifi_sel();
104	  int i;
105	
106	  for (i = 0; i < WIFI_AP_ROWS; i++)
107	    {
108	      const char *ssid = NULL;
109	      int rssi = 0;
110	      bool open = false;
111	      if (i < n)
112	        {
113	          dm_wifi_ap_get(i, &ssid, &rssi, &open);
114	        }
115	      if (s_ap_lbls[i])
116	        {
117	          if (ssid)
118	            {
119	              char line[40];
120	              lv_snprintf(line, sizeof(line), "%s%s", open ? "" : "* ",
121	                          ssid);
122	              lv_label_set_text(s_ap_lbls[i], line);
123	            }
124	          else
125	            {
126	              lv_label_set_text(s_ap_lbls[i], "—");
127	            }
128	        }
129	      if (s_ap_btns[i])
130	        {
131	          if (i == sel && i < n)
132	            {
133	              lv_obj_set_style_bg_color(s_ap_btns[i], lv_color_hex(C_BTN_HI),
134	                                        LV_PART_MAIN);
135	            }
136	          else
137	            {
138	              lv_obj_set_style_bg_color(s_ap_btns[i], lv_color_hex(C_BTN),
139	                                        LV_PART_MAIN);
140	            }
141	        }
142	    }
143	  if (s_join_btn)
144	    {
145	      if (sel >= 0 && sel < n)
146	        {
147	          lv_obj_set_style_bg_opa(s_join_btn, LV_OPA_COVER, LV_PART_MAIN);
148	        }
149	      else
150	        {
151	          lv_obj_set_style_bg_opa(s_join_btn, LV_OPA_50, LV_PART_MAIN);
152	        }
153	    }
154	}
