194	static void ap_click(lv_event_t *e)
195	{
196	  int i = (int)(uintptr_t)lv_event_get_user_data(e);
197	  const char *ssid = NULL;
198	  bool open = false;
199	
200	  if (i < 0 || i >= dm_wifi_ap_count())
201	    {
202	      return;
203	    }
204	  dm_wifi_set_sel(i);
205	  dm_wifi_ap_get(i, &ssid, NULL, &open);
206	  if (ssid)
207	    {
208	      strncpy(s_sel_ssid, ssid, sizeof(s_sel_ssid) - 1);
209	      s_sel_open = open;
210	    }
211	  refresh_ap_list();
212	}
