214	static void join_cb(lv_event_t *e)
215	{
216	  (void)e;
217	  int sel = dm_wifi_sel();
218	  if (sel < 0 || sel >= dm_wifi_ap_count())
219	    {
220	      return;
221	    }
222	  if (s_sel_open)
223	    {
224	      s_pw_buf[0] = 0;
225	      if (dm_wifi_connect(s_sel_ssid, NULL) == 0)
226	        {
227	          if (s_conn_ssid_l)
228	            {
229	              lv_label_set_text(s_conn_ssid_l, s_sel_ssid);
230	            }
231	          dm_show(PAGE_WIFI_CONN);
232	        }
233	      return;
234	    }
235	  s_pw_buf[0] = 0;
236	  if (s_pw_in)
237	    {
238	      lv_textarea_set_text(s_pw_in, "");
239	    }
240	  if (s_pw_ssid_l)
241	    {
242	      lv_label_set_text(s_pw_ssid_l, s_sel_ssid);
243	    }
244	  dm_show(PAGE_WIFI_PW);
245	}
