434	void dm_wifi_tick(void)
435	{
436	  if (g_dm.page == PAGE_WIFI)
437	    {
438	      if (dm_wifi_scan_ready())
439	        {
440	          dm_wifi_clear_scan_ready();
441	          s_need_list_refresh = true;
442	          refresh_ap_list();
443	          if (dm_wifi_ap_count() > 0)
444	            {
445	              char b[32];
446	              lv_snprintf(b, sizeof(b), "%s %d",
447	                          dm_t("找到", "Found"), dm_wifi_ap_count());
448	              set_tip(b, b);
449	            }
450	          else
451	            {
452	              set_tip("未找到热点，可再扫一次", "No APs, try scan again");
453	            }
454	        }
455	    }
456	
457	  if (g_dm.page == PAGE_WIFI_CONN)
458	    {
459	      if (dm_wifi_conn_ok())
460	        {
461	          dm_wifi_clear_conn_flags();
462	          refresh_wifi_header();
463	          if (s_done_title)
464	            {
465	              lv_label_set_text(s_done_title, dm_t("已连接", "Connected"));
466	              lv_obj_set_style_text_color(s_done_title, lv_color_hex(C_OK),
467	                                          LV_PART_MAIN);
468	            }
469	          if (s_done_icon)
470	            {
471	              lv_label_set_text(s_done_icon, "OK");
472	              lv_obj_set_style_text_color(s_done_icon, lv_color_hex(C_OK),
473	                                          LV_PART_MAIN);
474	            }
475	          if (s_done_sub)
476	            {
477	              lv_label_set_text(s_done_sub, dm_wifi_cur_ip());
478	            }
479	          dm_show(PAGE_WIFI_DONE);
480	        }
481	      else if (dm_wifi_conn_fail())
482	        {
483	          dm_wifi_clear_conn_flags();
484	          if (s_done_title)
485	            {
486	              lv_label_set_text(s_done_title,
487	                                dm_t("连接失败", "Failed"));
488	              lv_obj_set_style_text_color(s_done_title, lv_color_hex(C_HEART),
489	                                          LV_PART_MAIN);
490	            }
491	          if (s_done_icon)
492	            {
493	              lv_label_set_text(s_done_icon, "X");
494	              lv_obj_set_style_text_color(s_done_icon, lv_color_hex(C_HEART),
495	                                          LV_PART_MAIN);
496	            }
497	          if (s_done_sub)
498	            {
499	              lv_label_set_text(s_done_sub,
500	                                dm_t("检查密码或重试", "Check password"));
501	            }
502	          dm_show(PAGE_WIFI_DONE);
503	        }
504	    }
505	}
