25	static void trim_newline(char *text)
26	{
27	  size_t len;
28	
29	  if (text == NULL)
30	    {
31	      return;
32	    }
33	  len = strlen(text);
34	  while (len > 0 && (text[len - 1] == '\n' || text[len - 1] == '\r'))
35	    {
36	      text[--len] = '\0';
37	    }
38	}
