40	static int is_blank(const char *text)
41	{
42	  if (text == NULL || *text == '\0')
43	    {
44	      return 1;
45	    }
46	  while (*text != '\0')
47	    {
48	      if (!isspace((unsigned char)*text))
49	        {
50	          return 0;
51	        }
52	      text++;
53	    }
54	  return 1;
55	}
