57	/*
58	 * NSH 对 '"'"' 拼接支持不完整。
59	 * 策略：一般字符直接用单引号包起来；含单引号则拒绝，提示改密码/SSID。
60	 */
61	static int shell_quote_safe(char *out, size_t out_size, const char *input)
62	{
63	  size_t used;
64	  size_t n;
65	
66	  if (out == NULL || input == NULL || out_size < 3)
67	    {
68	      return -1;
69	    }
70	  if (strchr(input, '\'') != NULL)
71	    {
72	      return -1;
73	    }
74	
75	  n = strlen(input);
76	  if (n + 3 > out_size)
77	    {
78	      return -1;
79	    }
80	
81	  used = 0;
82	  out[used++] = '\'';
83	  memcpy(out + used, input, n);
84	  used += n;
85	  out[used++] = '\'';
86	  out[used] = '\0';
87	  return (int)used;
88	}
