156	static int connect_wifi(const char *ssid, const char *password)
157	{
158	  char qssid[WIFI_INPUT_MAX + 8];
159	  char qpass[WIFI_INPUT_MAX + 8];
160	  char command[WIFI_CMD_MAX];
161	
162	  if (shell_quote_safe(qpass, sizeof(qpass), password) < 0)
163	    {
164	      printf("[WiFi] 密码含单引号或过长，请改用不含 ' 的密码\n");
165	      return -1;
166	    }
167	  if (shell_quote_safe(qssid, sizeof(qssid), ssid) < 0)
168	    {
169	      printf("[WiFi] SSID 含单引号或过长\n");
170	      return -1;
171	    }
172	
173	  /* 分步执行，避免 NSH 对 && 支持不完整；psk 失败可单独看到 */
174	  snprintf(command, sizeof(command),
175	           "wapi psk %s %s 3", WIFI_IFNAME, qpass);
176	  if (run_command(command) < 0)
177	    {
178	      return -1;
179	    }
180	
181	  /* 可选：显式 WPA2 版本（文档 §1.3.2） */
182	  snprintf(command, sizeof(command),
183	           "wapi psk %s %s 3 2", WIFI_IFNAME, qpass);
184	  (void)run_command(command); /* 失败可忽略，有的栈只吃 3 参数形式 */
185	
186	  snprintf(command, sizeof(command),
187	           "wapi essid %s %s 1", WIFI_IFNAME, qssid);
188	  return run_command(command);
189	}
