290	      return EXIT_FAILURE;
291	    }
292	
293	  /* 5) 等 4 次握手 / 关联，再 DHCP（原稿 2s 偏短） */
294	  printf("\n[WiFi] 等待关联与 DHCP...\n");
295	  sleep(3);
296	
297	  for (retry = 0; retry < WIFI_RETRY_COUNT; retry++)
298	    {
