215	static void r528_wlan_work(void *arg)
216	{
217	  int ret;
218	
219	  (void)arg;
220	  s_wlan_attempts++;
221	  ret = realtek_wlan_bringup();
222	  syslog(LOG_INFO, "[r528-wlan] bringup try=%d ret=%d bus_ok=%d pol=%d\n",
223	         s_wlan_attempts, ret, s_wlan_bus_ok, s_power_pol);
224	
225	  if (s_wlan_bus_ok)
226	    {
227	      return;
228	    }
229	
230	  /* After each failed try, flip DIS polarity (active-high vs active-low) */
231	  s_power_pol = s_power_pol ? 0 : 1;
232	
233	  if (s_wlan_attempts < 6)
234	    {
235	      work_queue(HPWORK, &s_wlan_work, r528_wlan_work, NULL,
236	                 MSEC2TICK(4000));
237	    }
238	  else
239	    {
240	      syslog(LOG_ERR,
241	             "[r528-wlan] give up — check WIFI_DIS polarity / module power\n");
242	    }
243	}
