245	void r528_wlan_schedule_bringup(void)
246	{
247	  syslog(LOG_INFO,
248	         "[r528-wlan] schedule bringup +8s (sdc1 PG0-5, try DIS pol 0/1)\n");
249	  s_power_pol = 0; /* first try DIS=0 (enable if active-high disable) */
250	  work_queue(HPWORK, &s_wlan_work, r528_wlan_work, NULL, MSEC2TICK(8000));
251	}
