79	   * indicate if the command processor is available or zero if it is not.
80	   */
81	
82	  DEBUGASSERT(cmd != NULL);
83	
84	  /* Initialize attributes for task_spawn() (or posix_spawn()). */
85	
86	  errcode = posix_spawnattr_init(&attr);
