94	  param.sched_priority = CONFIG_SYSTEM_SYSTEM_PRIORITY;
95	  errcode = posix_spawnattr_setschedparam(&attr, &param);
96	  if (errcode != 0)
97	    {
98	      goto errout_with_attrs;
99	    }
100	
101	  errcode = posix_spawnattr_setstacksize(&attr,
102	                                         CONFIG_SYSTEM_SYSTEM_STACKSIZE);
103	  if (errcode != 0)
104	    {
105	      goto errout_with_attrs;
106	    }
107	
108	  /* If robin robin scheduling is enabled, then set the scheduling policy
109	   * of the new task to SCHED_RR before it has a chance to run.
110	   */
111	
112	#if CONFIG_RR_INTERVAL > 0
113	  errcode = posix_spawnattr_setschedpolicy(&attr, SCHED_RR);
114	  if (errcode != 0)
115	    {
116	      goto errout_with_attrs;
117	    }
118	
119	  errcode = posix_spawnattr_setflags(&attr,
