178	/**
179	 *	sdio_release_irq - release the IRQ for a SDIO function
180	 *	@func: SDIO function
181	 *
182	 *	Disable and release the IRQ for the given SDIO function.
183	 */
184	int realtek_sdio_release_irq(struct sdio_func *func)
185	{
186		int ret;
187		unsigned char reg;
188		struct realtek_sdio_dev *priv = (struct realtek_sdio_dev *)func;
189		struct sdio_dev_s *dev = priv->sdio_dev;
190		int function =func->num;
191		if (priv->irq_handler) {
192			priv->irq_handler = NULL;
193			priv->irq_thread_abort = 1;
194			nxsem_post(&priv->thread_signal);
195		}
196	
197		ret = sdio_io_rw_direct(dev, false, 0, SDIO_CCCR_INTEN, 0, &reg);
198		if (ret)
199			goto exit;
200	
201		reg &= ~(1 << function);
202	
203		/* Disable master interrupt with the last function interrupt */
204		if (!(reg & 0xFE))
205			reg = 0;
206	
207		ret = sdio_io_rw_direct(dev, true, 0, SDIO_CCCR_INTEN, reg, NULL);
208		if (ret)
209			goto exit;
210	
211	exit:
212		return 0;
213	}
