235	/* Split an arbitrarily sized data transfer into several
236	 * IO_RW_EXTENDED commands. */
237	static int sdio_io_rw_ext_helper(struct sdio_func *func, int write,
238		unsigned addr, int incr_addr, unsigned char *buf, unsigned size)
239	{
240		unsigned remainder = size;
241		int ret;
242		struct realtek_sdio_dev *priv = (struct realtek_sdio_dev *)func;
243		struct sdio_dev_s *dev = priv->sdio_dev;
244		while (remainder > func->cur_blksize) {
245			unsigned blocks;
246	
247			blocks = remainder / func->cur_blksize;					
248			size = blocks * func->cur_blksize;
249	
250			ret = sdio_io_rw_extended(dev, write,
251				func->num, addr, incr_addr, buf, func->cur_blksize,
252				blocks);
253			if (ret)
254				return ret;
255	
256			remainder -= size;
257			buf += size;
258			if (incr_addr)
259				addr += size;
260		}
261	
262		/* Write the remainder using byte mode. */
263		while (remainder > 0) {
264			ret = sdio_io_rw_extended(dev, write, func->num, addr,
265				 incr_addr, buf, size, 0);
266			if (ret)
267				return ret;
268	
269			remainder -= size;
270			buf += size;
271			if (incr_addr)
272				addr += size;
273		}
274		return 0;
275	}
