111	/*
112	 * Module power / reset per schematic:
113	 *   BT_RESETN (PG17/gpio4): low pulse then high
114	 *   Possible WIFI_DIS pins (PD21/PD22/PG18): set to s_power_pol
115	 * High DIS = disable WiFi on many modules → try pol=0 first.
116	 */
117	static int r528_wlan_power_on(void)
118	{
119	  syslog(LOG_INFO,
120	         "[r528-wlan] power seq pol=%d (gpio0/1/2 DIS cand, gpio4=BT_RESETN)\n",
121	         s_power_pol);
122	
123	  /* BT_RESETN reset pulse */
124	  wlan_gpio_write(WLAN_PIN_BT_RST, 0);
125	  usleep(WLAN_EN_LOW_US);
126	  wlan_gpio_write(WLAN_PIN_BT_RST, 1);
127	  usleep(100 * 1000);
128	
129	  wlan_gpio_write(WLAN_PIN_PD21, s_power_pol);
130	  wlan_gpio_write(WLAN_PIN_PD22, s_power_pol);
131	  wlan_gpio_write(WLAN_PIN_PG18, s_power_pol);
132	  usleep(WLAN_EN_HIGH_SETTLE);
133	
134	  syslog(LOG_INFO, "[r528-wlan] module control pins set pol=%d\n", s_power_pol);
135	  return 0;
136	}
