138	int realtek_wlan_bringup(void)
139	{
140	  int ret;
141	
142	  syslog(LOG_INFO, "[r528-wlan] begin bringup sdc%d only\n", WLAN_SDC_NO);
143	  wlan_check_firmware();
144	
145	  syslog(LOG_INFO,
146	         "[r528-wlan] set_sdio_param(sdc%d, CARD_ALWAYS_PRESENT)\n",
147	         WLAN_SDC_NO);
148	  set_sdio_param(WLAN_SDC_NO, 3, NULL);
149	
150	  ret = r528_wlan_power_on();
151	  if (ret < 0)
152	    {
153	      return ret;
154	    }
155	
156	  if (!s_sdio_host_inited)
157	    {
158	      syslog(LOG_INFO,
159	             "[r528-wlan] sdio host init sdc%d (PG0-PG5 pinmux)\n",
160	             WLAN_SDC_NO);
161	      g_sdio_dev = sdio_initialize(WLAN_SDC_NO);
162	      if (!g_sdio_dev)
163	        {
164	          syslog(LOG_ERR, "[r528-wlan] sdio_initialize(%d) fail\n",
165	                 WLAN_SDC_NO);
166	          return -1;
167	        }
168	      s_sdio_host_inited = 1;
169	      syslog(LOG_INFO, "[r528-wlan] sdio host sdc%d init ok\n",
170	             WLAN_SDC_NO);
171	    }
172	
173	  usleep(WLAN_PROBE_SETTLE);
174	
175	  if (!s_wlan_bus_ok)
176	    {
177	      syslog(LOG_INFO, "[r528-wlan] realtek_wl_sdio_init(sdc%d) probe...\n",
178	             WLAN_SDC_NO);
179	      ret = realtek_wl_sdio_init(g_sdio_dev);
180	      if (ret != 0)
181	        {
182	          syslog(LOG_ERR,
183	                 "[r528-wlan] realtek probe failed ret=%d pol=%d\n",
184	                 ret, s_power_pol);
185	          return ret;
186	        }
187	      syslog(LOG_INFO, "[r528-wlan] realtek probe success\n");
188	
189	      syslog(LOG_INFO, "[r528-wlan] realtek_wl_initialize(0) register wlan0\n");
190	      ret = realtek_wl_initialize(0);
191	      if (ret < 0)
192	        {
193	          syslog(LOG_ERR, "[r528-wlan] netdev/wlan0 register fail ret=%d\n",
194	                 ret);
195	          return ret;
196	        }
197	      s_wlan_bus_ok = 1;
198	      syslog(LOG_INFO, "[r528-wlan] wlan0 registered\n");
199	    }
200	
201	  syslog(LOG_INFO, "[r528-wlan] wifi_on(STA) — radio/firmware\n");
202	  ret = wifi_on(RTW_MODE_STA);
203	  if (ret < 0)
204	    {
205	      syslog(LOG_WARNING,
206	             "[r528-wlan] wifi_on(STA) ret=%d — wlan0 may still exist\n",
207	             ret);
208	      return 0;
209	    }
210	
211	  syslog(LOG_INFO, "[r528-wlan] bringup success, wlan0 ready for wapi\n");
212	  return 0;
213	}
