320	      rltk_wlan_running(priv->devnum) == false)
321	    {
322	        if (priv->devnum == 1 && rltk_wlan_running(0) == true)
323	        {
324	          DBG_INFO("wifi on coAP %d\n",mode);
325	          ret= wifi_on_coAP(mode);
326	          if (ret < 0)
327	          {
328	            goto errout;
329	          }
330	        }
331	        else{
332	          DBG_INFO("wifi on %d\n",mode);
333	          realtek_readMacAddr_From_File(ifname, priv->macaddr);
334	          realtek_readWL_PHY_REG_PG();
335	          wext_set_traffic_busy_thres(500);
336	          ret = wifi_on(mode);
337	          if (ret < 0)
338	          {
339	            goto errout;
340	          }
341	#ifdef CONFIG_X4B_FACTEST
342	          wifi_set_autoreconnect(1);
343	#endif
344	        }
345	    }     
346	
347	errout:
348	    if (ret)
349	    {
350	        mode = RTW_MODE_NONE;
351	    }
352	
353	    priv->mode = mode;
354	    if (mode == RTW_MODE_STA_AP)
355	    {
356	      priv->mode = RTW_MODE_AP;
357	      g_realtek_dev[0].mode = RTW_MODE_STA;
358	    }  
359	    
360	    return ret;
361	}
